# store/academy_library.py
"""
The academy library: courses you read in any order (no quiz needed), following the usual trading curriculum:
market basics → candlesticks → chart patterns → technical analysis → price action & market structure →
fundamentals & news → risk & psychology → strategies, then student start, gold, crypto & P2P, funded challenges,
indices, and practice & backtesting.

Each topic: key, title, summary (the cheat-sheet bullets), body (paragraphs), and optionally
  pic       a picture key (store/academy_charts.py diagrams)
  real      True for candlestick patterns: lessons show a real chart example (store/academy_examples.py) when found
  signal    e.g. 'Bullish reversal' (badge)
"""
C = []


def course(key, title, icon, blurb, topics):
    C.append({'key': key, 'title': title, 'icon': icon, 'blurb': blurb, 'topics': topics})


def t(key, title, summary, body, pic=None, signal=None, real=False):
    return {'key': key, 'title': title, 'summary': summary, 'body': body, 'pic': pic, 'signal': signal, 'real': real}


